-- Guest Hub H9 fix 4 (18 Nov 2026, Ahmed — DECISIONS.md 2026-11-18 «Guest Hub H9 fix 4: staff path speed, staff buttons by
-- id, the inbox red bar, reply-rule wording»). Generated by scripts/hub-fix4-migration.mjs from scripts/hub-fix4-migration.src.sql
-- and the latest definitions of the functions it edits — never edited once applied (CLAUDE.md §12: a fix is a new migration).
--   The staff path's stage times (public.hub_staff_timings — times, ids and token counts only). Staff quick replies by id,
--   acting once (public.hub_staff_buttons; «تم تطبيقها من قبل.» / «انتهت صلاحية هذا الطلب، أرسله من جديد.»). A reply rule's
--   lines say how it is applied («هطبّقها كده:»), never «هقولها للضيوف» — also after «للفرعين» and «امسح». The template
--   store's name check used a repetition count above 255, refused by PostgreSQL — every read since 15 Nov failed to store.
-- No unit mode, licence or switch changes. No phone number in this file. Every UPDATE / DELETE carries a WHERE.


-- ───────────────────────────────────────────── 1. the staff path's stage times ─────────────────────────────────────────────
-- One row per message from a staff or management number: WhatsApp's own time of the message (YCloud sendTime), YCloud's
-- event time, our receipt, the 2xx, then each stage as an ISO time (typing, stored, the model calls, the send, YCloud's
-- acceptance, delivered / read). Times, ids and token counts only — never a text, a name or a number. Kept with its message
-- (30 days — the staff messages' purge cascades).
create table public.hub_staff_timings (
  staff_message_id uuid primary key references public.hub_staff_messages (id) on delete cascade,
  kind text not null default 'other' check (kind in ('text', 'voice', 'tap', 'other')),
  provider_sent_at timestamptz,
  event_created_at timestamptz,
  received_at timestamptz,
  stages jsonb not null default '{}'::jsonb check (jsonb_typeof(stages) = 'object'),
  models jsonb not null default '[]'::jsonb check (jsonb_typeof(models) = 'array' and jsonb_array_length(models) <= 12),
  reply_provider_id text check (reply_provider_id is null or char_length(reply_provider_id) <= 200),
  reply_accepted_at timestamptz,
  delivered_at timestamptz,
  read_at timestamptz,
  fallback boolean not null default false,
  is_test boolean not null default false,
  created_at timestamptz not null default now()
);
comment on table public.hub_staff_timings is 'Guest Hub H9 fix 4 (18 Nov 2026): the stage times of each staff / management message — WhatsApp''s time, YCloud''s event, our receipt and 2xx, typing, the model calls (model, tokens, ms, fallback), the send and YCloud''s acceptance, delivered / read. No text, name or number.';
create index hub_staff_timings_reply on public.hub_staff_timings (reply_provider_id) where reply_provider_id is not null;
create index hub_staff_timings_created on public.hub_staff_timings (created_at desc);
alter table public.hub_staff_timings enable row level security;
revoke all on table public.hub_staff_timings from public, anon, authenticated;
grant all on table public.hub_staff_timings to service_role;

-- merged by message: the first value of each time wins, the stages and models add up
create function public.hub_staff_timing_record(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid := nullif(p ->> 'message_id', '')::uuid;
  v_stages jsonb := case when jsonb_typeof(p -> 'stages') = 'object' then p -> 'stages' else '{}'::jsonb end;
  v_models jsonb := case when jsonb_typeof(p -> 'models') = 'array' then p -> 'models' else '[]'::jsonb end;
  k text;
begin
  if v_id is null or not exists (select 1 from public.hub_staff_messages m where m.id = v_id) then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  -- every stage is a time (never a text)
  for k in select jsonb_object_keys(v_stages) loop
    if k !~ '^[a-z_0-9]{1,40}$' or jsonb_typeof(v_stages -> k) <> 'string' or (v_stages ->> k) !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.]+Z$' then
      raise exception 'hub_timing_stage' using errcode = '22023';
    end if;
  end loop;
  if jsonb_array_length(v_models) > 6 then v_models := '[]'::jsonb; end if;
  v_models := coalesce((select jsonb_agg(jsonb_build_object('model', left(coalesce(e ->> 'model', ''), 60), 'input_tokens', coalesce((e ->> 'input_tokens')::bigint, 0),
                                  'output_tokens', coalesce((e ->> 'output_tokens')::bigint, 0), 'ms', coalesce((e ->> 'ms')::integer, 0),
                                  'fallback', coalesce((e ->> 'fallback')::boolean, false), 'layer', left(coalesce(e ->> 'layer', ''), 20)))
                          from jsonb_array_elements(v_models) e), '[]'::jsonb);
  insert into public.hub_staff_timings as t (staff_message_id, kind, provider_sent_at, event_created_at, received_at, stages, models, reply_provider_id, reply_accepted_at, fallback, is_test)
  values (v_id, case when p ->> 'kind' in ('text', 'voice', 'tap', 'other') then p ->> 'kind' else 'other' end,
          nullif(p ->> 'provider_sent_at', '')::timestamptz, nullif(p ->> 'event_created_at', '')::timestamptz, nullif(p ->> 'received_at', '')::timestamptz,
          v_stages, v_models, nullif(left(coalesce(p ->> 'reply_provider_id', ''), 200), ''), nullif(p ->> 'reply_accepted_at', '')::timestamptz,
          coalesce((p ->> 'fallback')::boolean, false), coalesce((p ->> 'is_test')::boolean, false))
  on conflict (staff_message_id) do update
     set kind = case when t.kind = 'other' then excluded.kind else t.kind end,
         provider_sent_at = coalesce(t.provider_sent_at, excluded.provider_sent_at),
         event_created_at = coalesce(t.event_created_at, excluded.event_created_at),
         received_at = coalesce(t.received_at, excluded.received_at),
         stages = excluded.stages || t.stages,
         models = case when jsonb_array_length(t.models) + jsonb_array_length(excluded.models) <= 12 then t.models || excluded.models else t.models end,
         reply_provider_id = coalesce(excluded.reply_provider_id, t.reply_provider_id),
         reply_accepted_at = coalesce(t.reply_accepted_at, excluded.reply_accepted_at),
         fallback = t.fallback or excluded.fallback;
  return jsonb_build_object('ok', true);
end;
$$;

-- YCloud's later statuses of our reply to a colleague (sent / delivered / read): the first time of each
create function public.hub_staff_timing_status(p_ycloud_id text, p_status text, p_at timestamptz default null) returns integer
language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  if coalesce(p_ycloud_id, '') = '' or p_status not in ('delivered', 'read') then return 0; end if;
  update public.hub_staff_timings t
     set delivered_at = coalesce(t.delivered_at, coalesce(p_at, now())),
         read_at = case when p_status = 'read' then coalesce(t.read_at, coalesce(p_at, now())) else t.read_at end
   where t.reply_provider_id = p_ycloud_id;
  get diagnostics n = row_count;
  return n;
end;
$$;
revoke execute on function public.hub_staff_timing_record(jsonb), public.hub_staff_timing_status(text, text, timestamptz) from public, anon, authenticated;
grant execute on function public.hub_staff_timing_record(jsonb), public.hub_staff_timing_status(text, text, timestamptz) to service_role;

-- ───────────────────────────────────────────── 2. staff reply buttons by id ─────────────────────────────────────────────
-- Every quick reply sent to a staff or management number carries its own id «hubk:<20 letters>», bound here to the action
-- and the pending item (a card, a follow-up). A tap is routed by that id only — never by its title, never through a model —
-- and only once: a second tap of the same button (or of another button of the same message) gets «تم تطبيقها من قبل.»;
-- an unknown, foreign or day-old one «انتهت صلاحية هذا الطلب، أرسله من جديد.». The buttons sent before this migration
-- (hubl:<action>:<item>) keep the earlier matching, with the same fixed replies for an item already applied or gone.
create table public.hub_staff_buttons (
  id text primary key check (id ~ '^hubk:[a-z0-9]{20}$'),
  who text not null check (who ~ '^(slot|recipient):[0-9a-f-]{36}$'),
  action text not null check (action in ('ok', 'both', 'edit', 'del', 'save', 'no')),
  item uuid not null,
  staff_message_id uuid references public.hub_staff_messages (id) on delete cascade,
  used_at timestamptz,
  is_test boolean not null default false,
  created_at timestamptz not null default now()
);
comment on table public.hub_staff_buttons is 'Guest Hub H9 fix 4 (18 Nov 2026): the quick replies sent to staff / management numbers — each id names its action and pending item; a tap acts once (used_at).';
create index hub_staff_buttons_group on public.hub_staff_buttons (staff_message_id, item);
alter table public.hub_staff_buttons enable row level security;
revoke all on table public.hub_staff_buttons from public, anon, authenticated;
grant all on table public.hub_staff_buttons to service_role;

create function public.hub_staff_buttons_add(p_phone text, p_message uuid, p_buttons jsonb, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_who text := internal.hub_teacher(p_phone) ->> 'who';
  e jsonb;
  n integer := 0;
begin
  if v_who is null then return jsonb_build_object('ok', false, 'reason', 'not_teacher'); end if;
  if jsonb_typeof(p_buttons) <> 'array' or jsonb_array_length(p_buttons) not between 1 and 3 then raise exception 'hub_buttons' using errcode = '22023'; end if;
  for e in select * from jsonb_array_elements(p_buttons) loop
    insert into public.hub_staff_buttons (id, who, action, item, staff_message_id, is_test)
    values (e ->> 'id', v_who, e ->> 'action', (e ->> 'item')::uuid, p_message, coalesce(p_test, false))
    on conflict (id) do nothing;
    n := n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'n', n);
end;
$$;
revoke execute on function public.hub_staff_buttons_add(text, uuid, jsonb, boolean) from public, anon, authenticated;
grant execute on function public.hub_staff_buttons_add(text, uuid, jsonb, boolean) to service_role;

-- ───────────────────────────────────────────── 3. the staff events left from before ─────────────────────────────────────────────
-- On deploy: a teaching still waiting more than 10 minutes after its message reached us is closed with no reply, so no burst
-- of late confirmations reaches Ahmed or the staff (none was waiting when this was written; the count is in the audit row).
do $$
declare n integer;
begin
  update public.hub_teach_jobs j set status = 'failed', reason = 'stale', finished_at = now()
    from public.hub_staff_messages m
   where m.id = j.staff_message_id and j.status in ('pending', 'running') and m.created_at < now() - interval '10 minutes';
  get diagnostics n = row_count;
  raise notice 'hub fix 4: % stale staff teaching(s) closed without a reply', n;
end $$;


-- ───────────────────────────────────────────── 4. the functions it edits ─────────────────────────────────────────────

create or replace function public.hub_learn_command(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t jsonb := internal.hub_teacher(p ->> 'phone');
  v_cmd text := p ->> 'command';
  v_scope text := case when p ->> 'scope' in ('airport-road', 'shafa-road', 'both') then p ->> 'scope' end;
  v_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_who text := t ->> 'who';
  v_user uuid := nullif(t ->> 'owner_user', '')::uuid;
  v_label text := 'تعليم واتساب — ' || coalesce(t ->> 'name', '');
  v_verdict text;
  ch public.hub_channels;
  c public.hub_knowledge_cards;
  pd public.hub_teach_pending;
  v_job uuid;
  v_n integer;
  v_r jsonb;
  v_day date;
  -- H9 fix 1: the teaching (combined by code from the message and its follow-ups), the card it replaces, a follow-up
  v_body text := p ->> 'body';
  v_revises uuid := nullif(p ->> 'revises', '')::uuid;
  f public.hub_teach_followups;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  -- H9 fix 4: a quick reply by its own id
  v_btn public.hub_staff_buttons;
begin
  select * into ch from public.hub_channels where address = p ->> 'channel' order by created_at limit 1;
  -- H9 fix 4 (Ahmed, 18 Nov 2026): a tap on a staff quick reply acts once — by its id only (never its title, never a model)
  if v_cmd = 'tap' then
    select * into v_btn from public.hub_staff_buttons x where x.id = p ->> 'button' for update;
    if v_btn.id is null or v_btn.who is distinct from v_who or v_btn.created_at < now() - interval '24 hours' then
      return jsonb_build_object('handled', true, 'line', 'tap_expired');
    end if;
    -- the same button again, or another button of the same message already acted on
    if v_btn.used_at is not null or exists (select 1 from public.hub_staff_buttons y where y.staff_message_id is not distinct from v_btn.staff_message_id
                                          and y.item = v_btn.item and y.id <> v_btn.id and y.used_at is not null) then
      return jsonb_build_object('handled', true, 'line', 'tap_already');
    end if;
    update public.hub_staff_buttons x set used_at = now() where x.id = v_btn.id;
    v_cmd := case v_btn.action when 'ok' then 'btn_ok' when 'both' then 'btn_both' when 'edit' then 'btn_edit' when 'del' then 'btn_del' when 'save' then 'intent_yes' else 'intent_no' end;
    v_id := v_btn.item;
  end if;
  if v_cmd in ('yes', 'no') then
    -- only while «أستبدل القديمة؟» waits for this teacher (24 hours); otherwise the colleague chat answers
    select * into pd from public.hub_teach_pending where who = v_who and created_at > now() - interval '24 hours' for update;
    if pd.who is null then return jsonb_build_object('handled', false); end if;
    delete from public.hub_teach_pending where who = pd.who;
    if v_cmd = 'no' then return jsonb_build_object('handled', true, 'line', 'kept'); end if;
    if internal.hub_teach_verdict(t, pd.scope) <> 'ok' then return jsonb_build_object('handled', true, 'line', 'not_allowed'); end if;
    v_r := internal.hub_learn_insert('teach', pd.scope, v_who, t ->> 'name', v_user, pd.candidate, pd.conflicts, pd.is_test or v_test);
    if not coalesce((v_r ->> 'ok')::boolean, false) then return jsonb_build_object('handled', true, 'line', 'failed', 'reason', v_r ->> 'reason'); end if;
    update public.hub_teach_jobs set status = 'learned', card_id = (v_r ->> 'id')::uuid where id = pd.job_id;
    return jsonb_build_object('handled', true, 'line', 'replaced', 'vars', jsonb_build_object('wording', v_r ->> 'wording', 'n', v_r ->> 'n'), 'card_id', v_r ->> 'id');
  end if;
  -- H9 fix 1: the quick replies of a saved card («تمام» / «للفرعين» / «عدّل» / «امسح») — the teacher's own card only
  if v_cmd in ('btn_ok', 'btn_both', 'btn_edit', 'btn_del') then
    if internal.hub_teach_verdict(t, 'airport-road') = 'not_allowed' then return jsonb_build_object('handled', true, 'line', 'not_allowed'); end if;
    select * into c from public.hub_knowledge_cards k where k.id = v_id and k.learn_who = v_who and k.learn_kind = 'teach';
    -- H9 fix 4: an item already applied or gone — a short fixed reply, nothing done again
    if c.id is null then return jsonb_build_object('handled', true, 'line', 'tap_expired'); end if;
    if c.status = 'archived' then return jsonb_build_object('handled', true, 'line', case when v_cmd = 'btn_del' then 'tap_already' else 'tap_expired' end); end if;
    if c.status <> 'published' then return jsonb_build_object('handled', true, 'line', 'tap_expired'); end if;
    if v_cmd = 'btn_ok' then return jsonb_build_object('handled', true, 'line', 'ok_ack'); end if;
    if v_cmd = 'btn_del' then
      perform internal.hub_learn_archive(c.id, v_user, v_label);
      delete from public.hub_teach_followups x where x.who = v_who and x.card_id = c.id;
      return jsonb_build_object('handled', true, 'line', case when c.card_kind = 'rule' then 'rule_removed' else 'removed' end, 'vars', jsonb_build_object('wording', c.text_ar), 'card_id', c.id);
    end if;
    if v_cmd = 'btn_edit' then
      insert into public.hub_teach_followups (who, kind, card_id, body, scope, channel_id, is_test)
      values (v_who, 'edit', c.id, c.text_ar, internal.hub_card_scope(c), ch.id, v_test)
      on conflict (who) do update set kind = 'edit', card_id = excluded.card_id, body = excluded.body, scope = excluded.scope, link_name = null,
                                      channel_id = excluded.channel_id, is_test = excluded.is_test, created_at = now();
      return jsonb_build_object('handled', true, 'line', 'edit_ask');
    end if;
    -- «للفرعين»: Ahmed only (a manager teaches his own branch); a card already for both branches — nothing to do again
    if internal.hub_card_scope(c) = 'both' then return jsonb_build_object('handled', true, 'line', 'tap_already'); end if;
    v_verdict := internal.hub_teach_verdict(t, 'both');
    if v_verdict <> 'ok' then
      return jsonb_build_object('handled', true, 'line', v_verdict, 'vars', jsonb_build_object('branch', (select b from unnest(array['airport-road', 'shafa-road']) b
                                                   where not coalesce(t -> 'manager_branches', '[]'::jsonb) @> to_jsonb(b) limit 1)));
    end if;
    c := internal.hub_learn_rescope(c.id, 'both', v_user, v_label);
    return jsonb_build_object('handled', true, 'line', case when c.card_kind = 'rule' then 'rule_saved_both' else 'saved_both' end, 'card_id', c.id, 'scope', 'both',
      'vars', jsonb_build_object('wording', c.text_ar, 'expiry', c.expires_on));
  end if;
  -- «أسجّلها معلومة للضيوف؟» asked (once): the teaching waits for «سجّلها» / «لا»
  if v_cmd = 'ask_intent' then
    if internal.hub_teach_verdict(t, coalesce(v_scope, 'airport-road')) = 'not_allowed' then return jsonb_build_object('handled', false); end if;
    if char_length(btrim(coalesce(v_body, ''))) < 3 or v_scope is null then return jsonb_build_object('handled', false); end if;
    insert into public.hub_teach_followups (who, kind, card_id, body, scope, channel_id, is_test)
    values (v_who, 'intent', null, left(btrim(v_body), 4000), v_scope, ch.id, v_test)
    on conflict (who) do update set kind = 'intent', card_id = null, body = excluded.body, scope = excluded.scope, link_name = null,
                                    channel_id = excluded.channel_id, is_test = excluded.is_test, created_at = now()
    returning id into v_id;
    return jsonb_build_object('handled', true, 'line', 'intent_ask', 'followup_id', v_id);
  end if;
  if v_cmd in ('intent_yes', 'intent_no') then
    select * into f from public.hub_teach_followups x where x.who = v_who and x.kind = 'intent' and (v_id is null or x.id = v_id) and x.created_at > now() - interval '24 hours';
    delete from public.hub_teach_followups x where x.who = v_who and x.kind = 'intent';
    if v_cmd = 'intent_no' then return jsonb_build_object('handled', true, 'line', case when f.id is null and v_id is not null then 'tap_expired' else 'intent_no' end); end if;
    -- H9 fix 4: the question was already answered or has expired
    if f.id is null then return jsonb_build_object('handled', true, 'line', 'tap_expired'); end if;
    v_cmd := 'teach';
    v_body := f.body;
    v_scope := f.scope;
  end if;
  -- a correction after «عدّل» or a link that was asked for: that follow-up is answered by this teaching
  if v_cmd = 'teach' and nullif(p ->> 'followup', '') is not null then
    delete from public.hub_teach_followups x where x.who = v_who and x.id = (p ->> 'followup')::uuid;
  end if;
  if v_cmd = 'offer' then
    -- «عرض:» from Ahmed: offers are added from «العروض» (the same offer feeds the site and the booking price)
    if not coalesce((t ->> 'owner')::boolean, false) then return jsonb_build_object('handled', false); end if;
    return jsonb_build_object('handled', true, 'line', 'offer');
  end if;
  if v_cmd not in ('teach', 'remove_last', 'remove_n') then return jsonb_build_object('handled', false); end if;
  if internal.hub_teach_verdict(t, 'airport-road') = 'not_allowed' then return jsonb_build_object('handled', true, 'line', 'not_allowed'); end if;
  if v_cmd = 'teach' then
    if not internal.hub_learn_on('teach') then return jsonb_build_object('handled', true, 'line', 'teach_off'); end if;
    if v_scope is null then raise exception 'hub_learn_scope' using errcode = '22023'; end if;
    v_verdict := internal.hub_teach_verdict(t, v_scope);
    if v_verdict <> 'ok' then
      return jsonb_build_object('handled', true, 'line', v_verdict,
        'vars', jsonb_build_object('branch', case when v_scope = 'both' then (select b from unnest(array['airport-road', 'shafa-road']) b
                                                   where not coalesce(t -> 'manager_branches', '[]'::jsonb) @> to_jsonb(b) limit 1) else v_scope end));
    end if;
    if char_length(btrim(coalesce(v_body, ''))) < 3 then return jsonb_build_object('handled', true, 'line', 'empty'); end if;
    -- the card a follow-up replaces must be the teacher's own (else a new card)
    if v_revises is not null and not exists (select 1 from public.hub_knowledge_cards k where k.id = v_revises and k.learn_who = v_who and k.status = 'published') then
      v_revises := null;
    end if;
    if ch.id is null then return jsonb_build_object('handled', true, 'line', 'failed', 'reason', 'no_channel'); end if;
    insert into public.hub_teach_jobs (staff_message_id, channel_id, unit_id, who, scope, is_test, body, revises)
    values ((p ->> 'message_id')::uuid, ch.id, ch.unit_id, v_who, v_scope, v_test, left(btrim(v_body), 4000), v_revises)
    on conflict (staff_message_id) do nothing
    returning id into v_job;
    if v_job is null then return jsonb_build_object('handled', true, 'queued', false, 'reason', 'duplicate'); end if;
    if not v_test then perform internal.hub_agent_post('sweep'); end if;
    return jsonb_build_object('handled', true, 'queued', true, 'job_id', v_job);
  end if;
  if v_cmd = 'remove_last' then
    -- the teacher's latest teaching (24 hours), as long as nothing newer was taught by them
    select * into c from public.hub_knowledge_cards k where k.learn_who = v_who and k.learn_kind = 'teach' and k.learned_at > now() - interval '24 hours'
     order by k.learned_at desc limit 1;
    if c.id is null or c.status = 'archived' then return jsonb_build_object('handled', true, 'line', 'remove_none'); end if;
    perform internal.hub_learn_archive(c.id, v_user, v_label);
    return jsonb_build_object('handled', true, 'line', case when c.card_kind = 'rule' then 'rule_removed' else 'removed' end, 'vars', jsonb_build_object('wording', c.text_ar), 'card_id', c.id);
  end if;
  -- «امسح N»: the number of the latest daily report's line (the day it covers), else today's, else yesterday's
  v_n := nullif(p ->> 'n', '')::integer;
  if v_n is null or v_n < 1 then return jsonb_build_object('handled', true, 'line', 'remove_n_none', 'vars', jsonb_build_object('n', coalesce(v_n, 0))); end if;
  for v_day in select d from (select (select max(r.day) from public.hub_daily_reports r) as d, 1 as o union all select internal.riyadh_today(), 2
                               union all select internal.riyadh_today() - 1, 3) x where d is not null order by o loop
    select * into c from public.hub_knowledge_cards k where k.learn_day = v_day and k.learn_no = v_n and k.is_test = v_test limit 1;
    exit when c.id is not null;
  end loop;
  if c.id is null then return jsonb_build_object('handled', true, 'line', 'remove_n_none', 'vars', jsonb_build_object('n', v_n)); end if;
  if internal.hub_teach_verdict(t, internal.hub_card_scope(c)) <> 'ok' then return jsonb_build_object('handled', true, 'line', 'remove_n_other', 'vars', jsonb_build_object('n', v_n)); end if;
  perform internal.hub_learn_archive(c.id, v_user, v_label);
  return jsonb_build_object('handled', true, 'line', case when c.card_kind = 'rule' then 'rule_removed_n' else 'removed_n' end, 'vars', jsonb_build_object('n', v_n, 'wording', c.text_ar), 'card_id', c.id);
end;
$$;

create or replace function public.hub_template_read_store(p_channel uuid, p_item jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.hub_channels c where c.id = p_channel) then raise exception 'not_found' using errcode = '22023'; end if;
  if coalesce(p_item ->> 'name', '') !~ '^[a-z0-9_]+$' or char_length(p_item ->> 'name') > 512 or coalesce(p_item ->> 'language', '') !~ '^[a-z]{2,3}(_[A-Z]{2})?$'
     or char_length(coalesce(p_item ->> 'status', '')) not between 1 and 40 then raise exception 'hub_template_item' using errcode = '22023'; end if;
  insert into public.hub_templates as t (channel_id, name, language, category, status, reason, body, read_at)
  values (p_channel, p_item ->> 'name', p_item ->> 'language', nullif(left(coalesce(p_item ->> 'category', ''), 40), ''), upper(p_item ->> 'status'),
          nullif(left(coalesce(p_item ->> 'reason', ''), 300), ''), nullif(left(coalesce(p_item ->> 'body', ''), 2000), ''), now())
  on conflict (channel_id, name, language) do update
     set category = excluded.category, status = excluded.status, reason = excluded.reason, body = coalesce(excluded.body, t.body), read_at = excluded.read_at;
  return jsonb_build_object('ok', true);
end;
$$;
